namespace OpenTPW;

/// <summary>Every unproven sound rule (docs/AUDIO.md "Approximation register"); logged once when the sound service starts.</summary>
public static class AudioApproximations
{
	public static readonly (string Id, string Rule)[] All =
	{
		("AUDIO-018", "a positioned mono voice follows the software channel stage of QMixer.dll, which tp.exe selects for every voice (the request flag 1 is ORed in unconditionally at 0x6bc61b, so 0x6d23ab hands QSWaveMixConfigureChannel the mode 0x1000000, whose buffers have no DirectSound 3D object): the source's offset is rotated into the listener's basis (front and up from the camera matrix rows 0x7909b0 and 0x7909a0, right = up x front, 0x1800ce70, 0x1800cf10; the adapters' swap of y and z, 0x6d2640, 0x6d2a10, 0x6d2b20, and QMixer's negation of the third component, 0x18001020, make a rotation, so the camera axes need no mapping), the azimuth atan2(x, z) in degrees (0x1800cb10) becomes a DirectSound pan of 44.444 hundredths of a dB per degree mirrored behind the listener (0x18005730), the gain a volume of 2000 log10(gain) hundredths of a dB (0x1800ca40), and 0x18005830 sets both for a mono wave only (0x18005982 tests the format table 0x1803c6b4); the opposite channel is 10^(-|pan|/2000) of the level; a voice with the any-distance flag (event flag 0x200, speech, music, most interface sounds) is placed flat by the library (0x6bc51d: QSWaveMixSetPosition with the integers 0, 1, 0, 0x18007abd) and is centred at the voice's own gain. Open: QMixer's Doppler factor, which multiplies the frequency of every voice without the loop flag by 1 / (1 + v / 331.36) from the listener velocity tp.exe derives as the position change of each listener update (0x6b79d0 -> 0x6d27b0, 0x1800a1df-0x1800a2b7, 0x18005550), is not applied; the volume's quantisation to hundredths of a decibel is applied to the distance gain only, not to the product with the voice's own volume (at most 0.005 dB)"),
		("AUDIO-038", "the voice pool of 12 (tp.exe 0x6b62b0) ranks the held chains (screams) with the running sentences, placed sounds and one-shots of the event system by priority and ground distance (0x6bb9f0; a started any-distance voice sits at the origin of the sound space, where its sample start put it, 0x6bc51d), a voice entering only while its rank exceeds the pool's lowest (0x6b6bc0) and among equal ranks the newer voice keeping its slot (0x6b6a80 links a new voice at the head of the voice list); a voice out of range without the any-distance flag (event flag 0x200, voice flag 8 at 0x6bca44) has its sample stopped by mixer message 3 (0x6bca70 -> 0x6b8d60 -> 0x6bb7c0) and its handle at +0x24 cleared, is not ticked, and returns by the sample setup 0x6bc410: one-shots, loops and sentence segments restart from their beginning with a fresh volume, pitch and delay draw, a chain starts no new child but its children already playing play out. Open: a sentence stopped inside the decoder's last look-ahead (the 0x2400-byte read of 0x6bb510 reaching the end of the segment's data runs the refill 0x6bde00, which advances the selected descriptor) resumes on its successor, which this replay of the whole segment does not do; the sentence successor is chosen when a segment starts, not when the decoder's data runs out (EXT:sentence-prefetch); the initial submission's admission, the group-enable stop and restart of a voice (0x6bc760, the enable bytes +0x44..+0x47 of the sound system) and voices the mixer plays outside the event system, including the children a chain makes, which do not compete"),
		("AUDIO-040", "FADEOBJ uses configured quality > threshold, service-owned integer-decay tails, shared 100/250 ms polls, subtype-specific stop/continuation and terminal cleanup; the poll's effective volume is the worker thread's 53-bit x87 arithmetic (0x6bb860 on the thread of 0x6b9e30, control word 0x27F) and every main-thread computation the 24-bit one (0x7F). AUDIO-040 retains the host monotonic startup phase and the serialized poll/admission order of the original's Sleep(100/250) worker, which depends on the operating system's scheduler, and a missing host SoundQuality taking the loaded SAM DEFAULTQUALITY (supplied 50; FADETOGGLE 30) instead of the original user's saved preference; these are explicit compatibility policies, not observed original timing. AUDIO-038 admission/restart and existing general sentence approximations remain separate."),
	};

	private static bool logged;

	public static void LogOnce()
	{
		if ( logged )
			return;
		logged = true;
		foreach ( var (id, rule) in All )
			Log.Trace( $"[APPROX:{id}] {rule}" );
	}
}
